import numpy as np
import pandas as pd

def generate_weights(history, universe):
    universe = pd.Index(universe)
    if len(universe) == 0:
        return pd.Series(dtype=float)

    adj = history.get('adjusted_close')
    if adj is None:
        adj = history.get('close')
    if adj is None or not isinstance(adj, pd.DataFrame):
        return pd.Series(0.0, index=universe)

    cols = [c for c in universe if c in adj.columns]
    if len(cols) == 0:
        return pd.Series(0.0, index=universe)

    if not adj.index.is_monotonic_increasing:
        adj = adj.sort_index()
    px = adj[cols].tail(320).copy()
    n = len(px)
    if n < 40:
        return pd.Series(0.0, index=universe)

    def _mom(start_lag, end_lag):
        if n <= end_lag + 2:
            return pd.Series(np.nan, index=cols)
        end_pos = n - 1 - end_lag
        start_pos = max(0, n - 1 - start_lag)
        if end_pos <= start_pos:
            return pd.Series(np.nan, index=cols)
        return px.iloc[end_pos] / px.iloc[start_pos] - 1.0

    mom12 = _mom(252, 21)
    mom6 = _mom(126, 21)
    if n > 21:
        ret21 = px.iloc[-1] / px.iloc[n - 1 - 21] - 1.0
    else:
        ret21 = pd.Series(np.nan, index=cols)

    rets = px.pct_change()
    vol_window = min(126, max(2, n - 1))
    vol = rets.tail(vol_window).std() * np.sqrt(252.0)
    vol = vol.replace([np.inf, -np.inf], np.nan)

    last_price = px.iloc[-1]
    valid = last_price.notna() & (last_price > 0) & mom12.notna()
    valid = valid & (px.notna().sum() >= 60)

    if 'eligible' in history:
        edf = history['eligible']
        if isinstance(edf, pd.DataFrame):
            if not edf.index.is_monotonic_increasing:
                edf = edf.sort_index()
            ecols = [c for c in cols if c in edf.columns]
            if ecols:
                e_last = edf[ecols].tail(1)
                if len(e_last) > 0:
                    e = e_last.iloc[-1].reindex(cols).fillna(False).astype(bool)
                    valid = valid & e

    idx_valid = valid[valid].index
    if len(idx_valid) < 10:
        return pd.Series(0.0, index=universe)

    mom6 = mom6.where(mom6.notna(), mom12)
    mom12_v = mom12.loc[idx_valid]
    mom6_v = mom6.loc[idx_valid]
    vol_v = vol.loc[idx_valid].fillna(vol.loc[idx_valid].median())
    if vol_v.isna().all():
        vol_v = pd.Series(1.0, index=idx_valid)
    ret21_v = ret21.loc[idx_valid].fillna(ret21.loc[idx_valid].median())
    if ret21_v.isna().all():
        ret21_v = pd.Series(0.0, index=idx_valid)

    def rp(s):
        return s.rank(method='average', pct=True)

    score = (0.55 * rp(mom12_v) +
             0.25 * rp(mom6_v) +
             0.20 * (1.0 - rp(vol_v)) -
             0.20 * rp(ret21_v))
    score = score.replace([np.inf, -np.inf], np.nan).dropna()
    if len(score) < 10:
        return pd.Series(0.0, index=universe)

    n_side = min(50, len(score) // 2)
    if n_side < 1:
        return pd.Series(0.0, index=universe)

    longs = score.nlargest(n_side).index
    shorts = score.nsmallest(n_side).index
    w = min(0.02, 0.5 / float(n_side))
    weights = pd.Series(0.0, index=universe)
    weights.loc[longs] = w
    weights.loc[shorts] = -w

    gross = weights.abs().sum()
    if gross > 1.0 + 1e-12:
        weights = weights * (1.0 / gross)
    weights = weights.clip(-0.02, 0.02)
    return weights.reindex(universe).fillna(0.0)

import numpy as np
import pandas as pd

def _rank_pct(s):
    s = s.dropna()
    if len(s) == 0:
        return s
    return s.rank(method='average', pct=True) - 0.5

def generate_weights(history, universe):
    tickers = pd.Index(list(universe))
    if len(tickers) == 0:
        return pd.Series(dtype=float)

    px = history.get('adjusted_close')
    if px is None:
        return pd.Series(0.0, index=tickers)

    px = px.reindex(columns=tickers).astype(float)
    px = px.replace([np.inf, -np.inf], np.nan)
    if px.shape[0] < 30:
        return pd.Series(0.0, index=tickers)

    last_px = px.iloc[-1]

    ret = px / px.shift(1) - 1.0
    ret = ret.replace([np.inf, -np.inf], np.nan)

    r10 = px / px.shift(10) - 1.0
    r80 = px / px.shift(80) - 1.0
    vol20 = ret.rolling(20, min_periods=15).std()

    last_r10 = r10.iloc[-1]
    last_r80 = r80.iloc[-1]
    last_vol = vol20.iloc[-1]

    valid = (
        last_px.notna()
        & (last_px > 0)
        & last_r10.notna()
        & last_r80.notna()
        & last_vol.notna()
        & (last_vol > 0)
    )

    elig = history.get('eligible')
    if elig is not None:
        elig = elig.reindex(columns=tickers)
        if elig.shape[0] > 0:
            e_last = elig.iloc[-1]
            valid = valid & e_last.fillna(False).astype(bool)

    valid_t = valid[valid].index
    if len(valid_t) < 6:
        return pd.Series(0.0, index=tickers)

    rr10 = _rank_pct(last_r10.reindex(valid_t))
    rr80 = _rank_pct(last_r80.reindex(valid_t))
    rv = _rank_pct(last_vol.reindex(valid_t))

    score = -1.0 * rr10 + 0.55 * rr80 - 0.20 * rv
    score = score.replace([np.inf, -np.inf], np.nan).dropna()
    if len(score) < 4:
        return pd.Series(0.0, index=tickers)

    n_side = min(30, len(score) // 2)
    if n_side < 1:
        return pd.Series(0.0, index=tickers)

    order = score.sort_values(ascending=False)
    longs = order.index[:n_side]
    shorts = order.index[-n_side:]

    w = min(0.02, 0.5 / float(n_side))
    weights = pd.Series(0.0, index=tickers)
    weights.loc[longs] = w
    weights.loc[shorts] = -w

    gross = float(weights.abs().sum())
    if gross > 1.0:
        weights = weights * (1.0 / gross)

    return weights.replace([np.inf, -np.inf], 0.0).fillna(0.0)

import numpy as np
import pandas as pd

def generate_weights(history, universe):
    universe = pd.Index(universe)
    n = len(universe)
    if n == 0:
        return pd.Series(dtype=float)

    ac = history.get('adjusted_close')
    if ac is None:
        ac = history.get('close')
    if ac is None:
        return pd.Series(0.0, index=universe)

    cols = [t for t in universe if t in ac.columns]
    if len(cols) < 2:
        return pd.Series(0.0, index=universe)

    prices = ac.loc[:, cols].tail(300).astype(float).copy()
    if len(prices) < 25:
        return pd.Series(0.0, index=universe)

    rets = prices.pct_change(fill_method=None)
    last = prices.iloc[-1]
    vol = rets.tail(60).std(ddof=0)

    if len(prices) >= 22:
        r21 = prices.iloc[-1] / prices.iloc[-22] - 1.0
    else:
        r21 = pd.Series(np.nan, index=cols)

    if len(prices) >= 252:
        mom = prices.iloc[-22] / prices.iloc[-252] - 1.0
    elif len(prices) >= 126:
        mom = prices.iloc[-22] / prices.iloc[-126] - 1.0
    else:
        mom = pd.Series(np.nan, index=cols)

    vol_df = history.get('volume')
    if vol_df is not None:
        vcols = [t for t in cols if t in vol_df.columns]
        v = vol_df.loc[:, vcols].tail(20).astype(float)
        close_df = history.get('close')
        if close_df is not None:
            c = close_df.loc[:, vcols].tail(20).astype(float)
        else:
            c = prices.loc[:, vcols].tail(20)
        adv = (v * c).mean(skipna=True)
        adv = adv.reindex(cols)
    else:
        adv = pd.Series(np.nan, index=cols)

    eligible_df = history.get('eligible')
    if eligible_df is not None and len(eligible_df):
        erow = eligible_df.iloc[-1].reindex(cols)
        elig = erow.fillna(False).astype(bool)
    else:
        elig = pd.Series(True, index=cols)

    df = pd.DataFrame({'r21': r21, 'mom': mom, 'vol': vol, 'adv': adv, 'eligible': elig, 'last': last})
    df = df.replace([np.inf, -np.inf], np.nan)
    df = df[df['eligible'] & df['last'].notna() & df['r21'].notna() & df['vol'].notna() & (df['vol'] > 0)]

    if df['adv'].notna().sum() >= 5:
        df = df[df['adv'].notna() & (df['adv'] > 0)]
        if len(df) >= 5:
            q = df['adv'].quantile(0.20)
            df = df[df['adv'] >= q]

    if len(df) < 4:
        return pd.Series(0.0, index=universe)

    rank_rev = (-df['r21']).rank(method='average', pct=True)
    rank_mom = df['mom'].rank(method='average', pct=True).fillna(0.5)
    rank_lowvol = (-df['vol']).rank(method='average', pct=True)

    df = df.copy()
    df['score'] = 0.55 * rank_rev + 0.30 * rank_mom + 0.15 * rank_lowvol

    n_side = min(50, len(df) // 2)
    if n_side < 1:
        return pd.Series(0.0, index=universe)

    ordered = df.sort_values('score', ascending=False)
    longs = ordered.index[:n_side]
    shorts = ordered.index[-n_side:]

    side_gross = min(0.5, 0.02 * n_side)
    w = side_gross / n_side

    weights = pd.Series(0.0, index=universe)
    weights.loc[longs] = w
    weights.loc[shorts] = -w
    weights = weights.replace([np.inf, -np.inf], 0.0).fillna(0.0).clip(-0.02, 0.02)
    return weights.astype(float)

import numpy as np
import pandas as pd

def generate_weights(history, universe):
    tickers = pd.Index(list(universe))
    n = len(tickers)
    if n == 0:
        return pd.Series(dtype=float)
    zero = pd.Series(np.zeros(n, dtype=float), index=tickers)
    ac = history.get('adjusted_close')
    if ac is None or len(ac.index) < 5:
        return zero
    try:
        ac = ac.reindex(columns=tickers)
    except Exception:
        return zero
    dates = ac.index
    last_pos = len(dates) - 1
    signal_pos = last_pos
    if isinstance(dates, pd.DatetimeIndex) and last_pos >= 0:
        wd = dates.weekday.values
        mons = np.where(wd[:last_pos + 1] == 0)[0]
        if len(mons) > 0:
            signal_pos = mons[-1]
    L = 21
    if signal_pos < L + 1:
        return zero
    close_all = ac.values
    cur_close = close_all[last_pos]
    valid = np.isfinite(cur_close) & (cur_close > 1.0)
    elig = history.get('eligible')
    if elig is not None:
        try:
            e = elig.reindex(index=dates, columns=tickers)
            le = e.iloc[last_pos].values
            if le.dtype == bool:
                valid_e = le
            else:
                valid_e = np.array([(x is True) or (x == 1) for x in le], dtype=bool)
            if np.any(pd.notna(le)):
                valid &= valid_e
        except Exception:
            pass
    close_sig = close_all[:signal_pos + 1]
    ret = close_sig[-1] / close_sig[-1 - L] - 1.0
    valid &= np.isfinite(ret)
    vol = history.get('volume')
    if vol is not None:
        try:
            v = vol.reindex(index=dates, columns=tickers).values[:signal_pos + 1]
            if v.shape[0] >= 20:
                dv = np.nanmean(close_sig[-20:] * v[-20:], axis=0)
                valid &= np.isfinite(dv) & (dv > 0)
                if valid.sum() >= 20:
                    thresh = np.nanpercentile(dv[valid], 20)
                    valid &= dv >= thresh
        except Exception:
            pass
    idx = np.where(valid)[0]
    if len(idx) < 6:
        return zero
    raw_score = -ret[idx]
    scores = raw_score.copy()
    try:
        if close_sig.shape[0] >= 22:
            daily = close_sig[-21:] / close_sig[-22:-1] - 1.0
            vol20 = np.nanstd(daily, axis=0)
            vol20 = np.where(np.isfinite(vol20) & (vol20 > 1e-8), vol20, np.nan)
            adj = raw_score / vol20[idx]
            ok = np.isfinite(adj)
            scores = np.where(ok, adj, raw_score)
    except Exception:
        scores = raw_score
    order = np.argsort(scores)
    m = min(25, len(idx) // 2)
    if m < 1:
        return zero
    long_sel = idx[order[-m:]]
    short_sel = idx[order[:m]]
    wt = min(0.02, 0.5 / m)
    w = np.zeros(n, dtype=float)
    w[long_sel] = wt
    w[short_sel] = -wt
    w = np.nan_to_num(w, nan=0.0, posinf=0.0, neginf=0.0)
    w = np.clip(w, -0.02, 0.02)
    return pd.Series(w, index=tickers)

import numpy as np
import pandas as pd
import math


def _get_df(history, names):
    for name in names:
        obj = history.get(name)
        if isinstance(obj, pd.DataFrame):
            return obj
    return None


def generate_weights(history, universe):
    universe = pd.Index(universe)
    if len(universe) == 0:
        return pd.Series(dtype=float)

    price = _get_df(history, ['adjusted_close', 'close'])
    if price is None:
        return pd.Series(0.0, index=universe)

    price = price.reindex(columns=universe).iloc[-260:]
    if price.shape[0] < 25:
        return pd.Series(0.0, index=universe)

    last = price.iloc[-1]
    cnt = price.notna().sum()
    valid = last.notna() & (last > 2.0) & (cnt >= 60)

    vol_df = _get_df(history, ['volume'])
    if vol_df is not None:
        vol_df = vol_df.reindex(columns=universe).iloc[-60:]
        vmed = vol_df.tail(20).median()
        valid = valid & (vmed > 100000)

    elig_df = _get_df(history, ['eligible'])
    if elig_df is not None:
        e = elig_df.reindex(columns=universe).iloc[-1]
        valid = valid & e.fillna(True).astype(bool)

    rets = price / price.shift(1) - 1.0
    vol = rets.tail(60).std()
    vol = vol.replace(0.0, np.nan).clip(lower=0.005)

    def form(k):
        if price.shape[0] >= k + 1:
            return price.iloc[-1] / price.iloc[-k - 1] - 1.0
        return pd.Series(np.nan, index=universe)

    ret21 = form(21)
    ret5 = form(5)

    valid = valid & ret21.notna() & (ret21 < 1.5) & (ret21 > -0.75)
    if valid.sum() < 4:
        return pd.Series(0.0, index=universe)

    m21 = ret21[valid].mean()
    m5 = ret5[valid].mean()
    z21 = (ret21 - m21) / (vol * math.sqrt(21.0))
    z5 = (ret5 - m5) / (vol * math.sqrt(5.0))

    score = -(0.8 * z21 + 0.2 * z5)
    score = score.where(valid).replace([np.inf, -np.inf], np.nan).dropna()

    if len(score) < 10:
        score = (-(0.8 * ret21 + 0.2 * ret5)).where(valid)
        score = score.replace([np.inf, -np.inf], np.nan).dropna()

    if len(score) < 2:
        return pd.Series(0.0, index=universe)

    m = len(score)
    n_side = min(50, m // 2)
    if n_side < 1:
        n_side = 1

    sorted_score = score.sort_values(ascending=False)
    long_names = sorted_score.index[:n_side]
    short_names = sorted_score.index[-n_side:]

    w = min(0.5 / n_side, 0.02)
    weights = pd.Series(0.0, index=universe)
    weights.loc[long_names] += w
    weights.loc[short_names] -= w

    net = weights.sum()
    if abs(net) > 1e-12:
        idx = weights.index[weights != 0.0]
        if len(idx) > 0:
            weights.loc[idx] -= net / len(idx)

    weights = weights.clip(-0.02, 0.02)
    gross = weights.abs().sum()
    if gross > 1.0:
        weights = weights * (1.0 / gross)

    return weights.fillna(0.0).astype(float)

import pandas as pd
import numpy as np

def generate_weights(history, universe):
    universe = pd.Index(universe)
    if len(universe) == 0:
        return pd.Series(dtype=float)

    adj_close = {}
    volume = {}
    eligible_last = {}
    for t in universe:
        df = history.get(t)
        if df is None or len(df) == 0:
            eligible_last[t] = False
            continue
        if 'adjusted_close' in df.columns:
            adj_close[t] = df['adjusted_close']
        elif 'close' in df.columns:
            adj_close[t] = df['close']
        else:
            eligible_last[t] = False
            continue
        if 'volume' in df.columns:
            volume[t] = df['volume']
        if 'eligible' in df.columns and len(df) > 0:
            eligible_last[t] = bool(df['eligible'].iloc[-1])
        else:
            eligible_last[t] = True

    if not adj_close:
        return pd.Series(0.0, index=universe)

    close_df = pd.DataFrame(adj_close).reindex(columns=universe).sort_index()
    if len(close_df) < 150:
        return pd.Series(0.0, index=universe)

    rets = close_df.pct_change()
    mom = close_df.shift(5) / close_df.shift(126) - 1.0
    vol = rets.rolling(20).std()

    if volume:
        vol_df = pd.DataFrame(volume).reindex(columns=universe).sort_index()
        dollar_vol = close_df * vol_df
        liq = dollar_vol.rolling(20).median()
    else:
        liq = pd.DataFrame(np.nan, index=close_df.index, columns=universe)

    last_mom = mom.iloc[-1]
    last_vol = vol.iloc[-1]
    last_liq = liq.iloc[-1] if len(liq) > 0 else pd.Series(np.nan, index=universe)
    last_close = close_df.iloc[-1]
    elig = pd.Series(eligible_last).reindex(universe).fillna(False).astype(bool)

    valid = (
        last_close.notna()
        & last_mom.notna()
        & last_vol.notna()
        & (last_vol > 0)
        & (last_vol < 0.15)
        & (last_liq > 1e6)
        & elig
    )
    candidates = universe[valid]
    if len(candidates) < 20:
        return pd.Series(0.0, index=universe)

    m = last_mom[candidates]
    v = last_vol[candidates]
    mom_rank = m.rank(pct=True)
    vol_rank = v.rank(pct=True)
    score = mom_rank - 0.3 * vol_rank

    n_side = min(50, len(candidates) // 2)
    if n_side < 10:
        return pd.Series(0.0, index=universe)

    ranked = score.sort_values(ascending=False)
    longs = ranked.head(n_side).index
    shorts = ranked.tail(n_side).index

    w = min(0.5 / n_side, 0.02)
    weights = pd.Series(0.0, index=universe)
    weights[longs] = w
    weights[shorts] = -w
    return weights.fillna(0.0)

import numpy as np
import pandas as pd


def _rank_pct(s):
    return s.rank(method="average", pct=True, na_option="keep")


def generate_weights(history, universe):
    universe = pd.Index(universe)
    zero = pd.Series(0.0, index=universe, dtype=float)
    if len(universe) == 0:
        return zero

    try:
        adj = history.get("adjusted_close")
        if adj is None or adj.empty:
            adj = history.get("close")
    except Exception:
        adj = None
    if adj is None or adj.empty:
        return zero

    cols = [c for c in universe if c in adj.columns]
    if len(cols) == 0:
        return zero

    adj = adj[cols]
    idx = adj.index
    if len(idx) < 30:
        return zero

    last_date = idx[-1]
    try:
        nxt = last_date + pd.offsets.BDay(1)
        at_month_end = (nxt.year != last_date.year) or (nxt.month != last_date.month)
    except Exception:
        at_month_end = False

    if at_month_end:
        asof = last_date
    else:
        try:
            months = pd.Series(idx, index=idx).groupby([idx.year, idx.month]).max()
            asof = months.iloc[-2] if len(months) >= 2 else idx[0]
        except Exception:
            asof = idx[-1]

    pos = int(idx.searchsorted(asof, side="right"))
    if pos <= 0:
        return zero

    start = max(0, pos - 330)
    px = adj.iloc[start:pos]
    if len(px) < 30:
        return zero

    ret = px / px.shift(1) - 1.0
    ret = ret.replace([np.inf, -np.inf], np.nan)

    mom = px.shift(21) / px.shift(252) - 1.0
    rev = -(px / px.shift(21) - 1.0)
    vol = ret.tail(63).std()

    last = px.iloc[-1].reindex(cols)
    m = mom.iloc[-1].reindex(cols)
    r = rev.iloc[-1].reindex(cols)
    v = vol.iloc[-1].reindex(cols)

    score = 0.40 * _rank_pct(m) + 0.40 * _rank_pct(r) - 0.20 * _rank_pct(v)

    valid = last.notna() & (last > 0) & score.notna() & m.notna() & r.notna()

    try:
        elig = history.get("eligible")
    except Exception:
        elig = None
    if elig is not None:
        ecols = [c for c in cols if c in elig.columns]
        if len(ecols) > 0:
            e = elig[ecols]
            epos = int(e.index.searchsorted(asof, side="right"))
            if epos > 0:
                ev = e.iloc[epos - 1].reindex(cols).fillna(True).astype(bool)
                valid = valid & ev

    try:
        volume = history.get("volume")
    except Exception:
        volume = None
    if volume is not None and not volume.empty:
        vcols = [c for c in cols if c in volume.columns]
        if len(vcols) > 0:
            vv = volume[vcols]
            vpos = int(vv.index.searchsorted(asof, side="right"))
            if vpos > 0:
                vs = vv.iloc[max(0, vpos - 21):vpos]
                pxs = px[vcols].tail(21)
                adv = (vs.tail(21).reindex(index=pxs.index) * pxs).mean()
                liq_ok = adv > 0.0
                liq_ok = liq_ok.reindex(cols).fillna(True).astype(bool)
                valid = valid & liq_ok

    cand = score[valid].dropna()

    if len(cand) < 2:
        alt = 0.60 * _rank_pct(r) - 0.40 * _rank_pct(v)
        valid_alt = last.notna() & (last > 0) & alt.notna() & r.notna()
        if elig is not None and len(ecols) > 0 and epos > 0:
            valid_alt = valid_alt & ev
        cand = alt[valid_alt].dropna()

    if len(cand) < 2:
        return zero

    n = min(50, len(cand) // 2)
    if n < 1:
        return zero

    order = cand.sort_values(ascending=False)
    longs = order.index[:n]
    shorts = order.index[-n:]

    w = min(0.02, 0.5 / float(n))
